import { plural } from './format';
import type { RunResult } from './run';

const label = (s: string): string => s.padEnd(10, ' ');
const CONT = ' '.repeat(10);

export function formatResultText(r: RunResult): string {
  const lines: string[] = [];
  const w = r.query.window;
  const windowText =
    w.kind === 'event'
      ? `${w.start} to ${w.end === 'close' ? 'the regular-hours close' : w.end === 'session_close' ? 'the session close' : w.end} New York time, judged on ${w.barMinutes}-minute bars`
      : `a state outcome, known at ${w.knownAt} New York time`;
  const days = r.sessions.firstDay === null ? 'no trading days in range' : `${r.sessions.firstDay} to ${r.sessions.lastDay}`;
  lines.push(`Setup Odds ${r.engineVersion}, calendar ${r.calendarVersion}`);
  lines.push(label('Setup') + r.query.setup);
  lines.push(label('Outcome') + r.query.outcome);
  lines.push(label('Window') + windowText);
  lines.push(label('Data') + `${r.data.label}, ${r.data.bars} ${plural(r.data.bars, 'bar', 'bars')}, ${days}`);
  lines.push(
    label('Sessions') + `${r.sessions.inRange} in range, ${r.sessions.missing} missing, ${r.sessions.thin} thin, ${r.sessions.unmeasured} not measurable`,
  );
  lines.push('');
  const d = r.display;
  lines.push(label('Setup') + d.setup);
  lines.push(label('Baseline') + d.baseline);
  if (d.lift !== null) lines.push(label('Lift') + d.lift);
  if (d.halves === null) lines.push(label('Halves') + 'too few sessions to split');
  else {
    lines.push(label('Halves') + d.halves[0]);
    lines.push(CONT + d.halves[1]);
  }
  if (d.years.length === 0) lines.push(label('By year') + 'none');
  d.years.forEach((y, i) => lines.push((i === 0 ? label('By year') : CONT) + y));
  if (d.timing !== null) {
    lines.push(label('Timing') + d.timing);
    for (const h of d.histogram ?? []) lines.push(CONT + h);
  }
  d.warnings.forEach((m, i) => lines.push((i === 0 ? label('Warnings') : CONT) + '- ' + m));
  return lines.join('\n') + '\n';
}
